+	}()
+
+	if _, err := connection.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
+		version bigint PRIMARY KEY,
+		name text NOT NULL,
+		digest text NOT NULL CHECK (digest ~ '^[a-f0-9]{64}$'),
+		applied_at timestamptz NOT NULL DEFAULT now()
+	)`); err != nil {
+		return fmt.Errorf("create migration ledger: %w", err)
+	}
+
+	entries, err := fs.ReadDir(migrationFiles, "migrations")
+	if err != nil {
+		return fmt.Errorf("read migrations: %w", err)
+	}
+	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
+	for _, entry := range entries {
+		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".sql") {
+			continue
+		}
+		versionText, _, ok := strings.Cut(entry.Name(), "_")
+		if !ok {
+			return fmt.Errorf("invalid migration filename %q", entry.Name())
+		}
+		version, err := strconv.ParseInt(versionText, 10, 64)
+		if err != nil {
+			return fmt.Errorf("invalid migration version %q: %w", entry.Name(), err)
+		}
+		body, err := migrationFiles.ReadFile(path.Join("migrations", entry.Name()))
+		if err != nil {
+			return fmt.Errorf("read migration %q: %w", entry.Name(), err)
+		}
+		sum := sha256.Sum256(body)
+		digest := hex.EncodeToString(sum[:])
+
+		var stored string
+		err = connection.QueryRow(ctx,
+			`SELECT digest FROM schema_migrations WHERE version=$1`, version).Scan(&stored)
+		if err == nil {
+			if stored != digest {
+				return fmt.Errorf("migration %d digest changed", version)
+			}
+			continue
+		}
+		if err != pgx.ErrNoRows {
+			return fmt.Errorf("read migration %d: %w", version, err)
+		}
+		tx, err := connection.Begin(ctx)
+		if err != nil {
+			return fmt.Errorf("begin migration %d: %w", version, err)
+		}
+		if _, err = tx.Exec(ctx, string(body)); err == nil {
+			_, err = tx.Exec(ctx,
