			return Run{}, nil, fmt.Errorf("%w: run execution binding", ErrInvalid)
		}
		execution := command.Execution
		next.Execution, next.CandidateCommit = &execution, command.CandidateCommit
		next.State, eventType = RunStateVerifying, "RUN_EXECUTED"
	case RecordRunVerification:
		if r.State != RunStateVerifying {
			return Run{}, nil, ErrInvalidTransition
		}
		if meta.Actor.Kind != ActorVerificationService {
			return Run{}, nil, ErrUnauthorized
		}
		if command.CandidateCommit != r.CandidateCommit {
			return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid)
		}
		if err := command.Evidence.Validate(); err != nil {
			return Run{}, nil, err
		}
		evidence := command.Evidence
		next.Verification, next.State, eventType = &evidence, RunStateReviewing, "RUN_VERIFIED"
	case RecordRunReview:
		if r.State != RunStateReviewing {
			return Run{}, nil, ErrInvalidTransition
		}
		if meta.Actor.Kind != ActorReviewService {
			return Run{}, nil, ErrUnauthorized
		}
		if command.CandidateCommit != r.CandidateCommit {
			return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid)
		}
		if err := command.Review.Validate(); err != nil {
			return Run{}, nil, err
		}
		review := command.Review
		next.Review, next.State, eventType = &review, RunStateAwaitingApproval, "RUN_REVIEWED"
	case ApproveRun:
		if r.State != RunStateAwaitingApproval {
			return Run{}, nil, ErrInvalidTransition
		}
		if meta.Actor.Kind != ActorHuman {
			return Run{}, nil, ErrUnauthorized
		}
		if command.CandidateCommit != r.CandidateCommit {
			return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid)
		}
		if err := validateBoundArtifact(r.Review, command.Review, "run review"); err != nil {
