		}
		if err := command.Approval.Validate(); err != nil {
			return Run{}, nil, err
		}
		approval := command.Approval
		next.Approval, next.State, eventType = &approval, RunStateMergeReady, "RUN_APPROVED"
	case RejectRun:
		if r.State != RunStateAwaitingApproval {
			return Run{}, nil, ErrInvalidTransition
		}
		if meta.Actor.Kind != ActorHuman {
			return Run{}, nil, ErrUnauthorized
		}
		if command.CandidateCommit != r.CandidateCommit {
			return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid)
		}
		if err := validateBoundArtifact(r.Review, command.Review, "run review"); err != nil {
			return Run{}, nil, err
		}
		if err := validateReason(command.Reason); err != nil {
			return Run{}, nil, err
		}
		next.State, eventType = RunStateRejected, "RUN_REJECTED"
	case RecordMerge:
		if r.State != RunStateMergeReady {
			return Run{}, nil, ErrInvalidTransition
		}
		if meta.Actor.Kind != ActorMergeService {
			return Run{}, nil, ErrUnauthorized
		}
		if command.CandidateCommit != r.CandidateCommit {
			return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid)
		}
		if err := validateBoundArtifact(r.Approval, command.Approval, "run approval"); err != nil {
			return Run{}, nil, err
		}
		if err := command.Merge.Validate(); err != nil {
			return Run{}, nil, err
		}
		merge := command.Merge
		next.Merge, next.State, eventType = &merge, RunStateMerged, "RUN_MERGED"
	case FailRun:
		if !trustedOperationalActor(meta.Actor.Kind) {
			return Run{}, nil, ErrUnauthorized
		}
		if err := command.Evidence.Validate(); err != nil {
			return Run{}, nil, err
		}
		if err := validateReason(command.Reason); err != nil {
			return Run{}, nil, err
		}
		next.State, eventType = RunStateFailed, "RUN_FAILED"
	case CancelRun:
		if meta.Actor.Kind != ActorHuman {
			return Run{}, nil, ErrUnauthorized
		}
		if err := validateReason(command.Reason); err != nil {
			return Run{}, nil, err
		}
		next.State, eventType = RunStateCancelled, "RUN_CANCELLED"
	default:
		return Run{}, nil, fmt.Errorf("%w: unsupported completion command", ErrInvalid)
	}
	next.Revision++
	next.UpdatedAt = meta.Timestamp.UTC()
	return next, []Event{newRunEvent(next, meta, eventType, nil)}, nil
}

